mapper.update:
update qxx_wm_sales_apply_line
set posted_qty = #{postedQty},
    line_status = #{lineStatus},
    update_time = now()
where apply_id = #{applyId}
  and factory_id = #{factoryId}
  and external_line_id = #{externalLineId}

mapper.select:
select l.sales_order_line_id as sales_order_line_id, ifnull(sum(l.apply_qty), 0) as apply_qty from qxx_wm_sales_apply_line l inner join qxx_wm_sales_apply a on a.apply_id = l.apply_id and a.factory_id = l.factory_id where a.external_order_no = #{externalOrderNo} and a.factory_id = #{factoryId} and a.status <> 'CANCELED' and l.sales_order_line_id is not null
and a.apply_id <> #{excludeApplyId}
group by l.sales_order_line_id
